6	function validatePolicy(policy, logger) {
7	  if (policy.length === 0) {
8	    throwMsg("Policy array must contain at least one entry.", "error", logger);
9	  }
10	  policy.forEach((policy2, index) => {
11	    if (!policy2.userAgent) {
12	      throwMsg(`policy[${index}].userAgent is required.`, "error", logger);
13	    }
14	    if (!policy2.allow && !policy2.disallow || policy2.allow?.length === 0 && policy2.disallow?.length === 0) {
15	      throwMsg(
16	        `policy[${index}] must have at least one 'disallow' or 'allow' entry.`,
17	        "error",
18	        logger
19	      );
20	    }
21	    if (policy2.crawlDelay) {
22	      if (typeof policy2.crawlDelay !== "number" || policy2.crawlDelay < 0.1 || policy2.crawlDelay > 60) {
23	        throwMsg(
24	          `policy[${index}].crawlDelay must be between 0.1 and 60 seconds.`,
25	          "error",
26	          logger
27	        );
28	      }
29	    }
30	  });
31	}
32	function generatePolicyContent(policy) {
33	  return policy.map((rule) => {
34	    let content = `User-agent: ${Array.isArray(rule.userAgent) ? rule.userAgent.join("\nUser-agent: ") : rule.userAgent || "*"}
35	`;
36	    if (rule.allow) {
37	      const allowPaths = Array.isArray(rule.allow) ? rule.allow : [rule.allow];
38	      allowPaths.forEach((path2) => content += `Allow: ${path2}
39	`);
40	    }
41	    if (rule.disallow) {
42	      const disallowPaths = Array.isArray(rule.disallow) ? rule.disallow : [rule.disallow];
43	      disallowPaths.forEach(
44	        (path2) => content += `Disallow: ${path2}
45	`
46	      );
47	    }
48	    if (rule.crawlDelay)
49	      content += `Crawl-delay: ${rule.crawlDelay}
50	`;
51	    if (rule.cleanParam) {
52	      const cleanParams = Array.isArray(rule.cleanParam) ? rule.cleanParam : [rule.cleanParam];
53	      cleanParams.forEach(
54	        (param) => content += `Clean-param: ${param}
55	`
56	      );
57	    }
58	    return content;
59	  }).join("\n");
60	}
61	function validateSitemapUrl(url) {
62	  const urlPattern = /^(https?:\/\/)[^\s/$.?#].[^\s]*\.(xml|xml\.gz|txt|txt\.gz|json|xhtml)$/i;
63	  return urlPattern.test(url);
64	}
65	function generateSitemapContent(options, siteHref, logger) {
66	  if (!options.sitemap)
67	    return "";
68	  if (options.sitemap === true) {
69	    if (siteHref) {
70	      const defaultSitemap = `${siteHref}sitemap-index.xml`;
71	      return `Sitemap: ${defaultSitemap}`;
72	    } else {
73	      logger.warn(
74	        "`sitemap` is configured as true, but `AstroConfig.site` is not provided. Failed to generate default sitemap URL."
75	      );
76	      return "";
77	    }
78	  }
79	  const sitemaps = Array.isArray(options.sitemap) ? options.sitemap : [options.sitemap];
80	  const validSitemaps = sitemaps.filter((url) => {
81	    if (validateSitemapUrl(url)) {
82	      return true;
83	    } else {
84	      logger.warn(`\x1B[33mInvalid Sitemap URL: ${url}\x1B[33m`);
85	      return false;
86	    }
87	  });
88	  return validSitemaps.map((url) => `Sitemap: ${url}`).join("\n") + "\n";
89	}
90	function validateHost(host, logger) {
91	  const hostPattern = /^(?=.{1,253}$)(?:(?!-)[a-zA-Z0-9-]{1,63}(?<!-)\.)+[a-zA-Z]{2,63}$/;
92	  if (!hostPattern.test(host)) {
93	    throwMsg(
94	      "Host is invalid. It should be a valid domain like 'www.example.com'",
95	      "error",
96	      logger
97	    );
98	  }
99	}
100	function generateHostContent(options, logger) {
101	  if (options.host) {
102	    validateHost(options.host, logger);
103	    return `Host: ${options.host}
104	`;
105	  }
106	  return "";
107	}
108	function throwMsg(msg, type, logger) {
109	  const formattedMsg = {
110	    warn: () => logger.warn(`\x1B[33mWarning: ${msg}\x1B[0m`),
111	    error: () => {
112	      logger.error(`\x1B[31m${msg}\x1B[0m`);
113	      throw new Error(msg);
114	    }
115	  };
116	  formattedMsg[type]?.();
117	}
118	function generate(options, siteMapHref, logger) {
119	  if (!options.policy || options.policy.length === 0) {
120	    throwMsg("Policy configuration is required.", "error", logger);
121	  }
122	  validatePolicy(options.policy, logger);
123	  const content = [
124	    generatePolicyContent(options.policy),
125	    generateSitemapContent(options, siteMapHref, logger),
126	    generateHostContent(options, logger)
127	  ].join("\n");
128	  return content.trim();
129	}
130	function logInfo(fileSize, logger, destDir) {
131	  const sizeLimit = 10;
132	  if (fileSize > sizeLimit) {
133	    console.log(
134	      `
135	\x1B[42m\x1B[30m Generating 'robots.txt' file \x1B[39m\x1B[0m`
136	    );
137	    const warnMsg = [
138	      `\x1B[33m(!) 'robots.txt' file size is ${fileSize} KB.`,
139	      `- Keep it under ${sizeLimit} KB for best results.\x1B[0m
140	`
141	    ];
142	    console.log(warnMsg.join("\n"));
143	  }
144	  logger.info(
145	    `\`robots.txt\` (${fileSize}KB) created at \`${path.relative(process.cwd(), destDir)}\``
146	  );
147	}
148	
149	function getFileSizeInKilobytes(fileBuffer) {
150	  return Buffer.byteLength(fileBuffer, "utf8") / 1024;
151	}
152	
153	const defaults = {
154	  policy: [
155	    {
156	      userAgent: "*",
157	      allow: "/"
158	    }
159	  ],
160	  sitemap: true,
161	  host: null
162	};
163	function robots(options) {
164	  let config;
165	  let finalSiteMapHref;
166	  const filename = "robots.txt";
167	  const opts = { ...defaults, ...options };
168	  return {
169	    name: "astro-robots",
170	    hooks: {
171	      "astro:config:setup": ({ config: cfg }) => {
172	        config = cfg;
173	        if (config.site) {
174	          finalSiteMapHref = new URL(config.base, config.site).href;
175	        }
176	      },
177	      "astro:server:setup": ({ server, logger }) => {
178	        server.middlewares.use(async (req, res, next) => {
179	          if (req.url?.startsWith(`/${filename}`)) {
180	            res.setHeader("Content-Type", "text/plain");
181	            res.setHeader("Cache-Control", "no-cache");
182	            res.end(generate(opts, finalSiteMapHref, logger));
183	          } else {
184	            next();
185	          }
186	        });
187	      },
188	      "astro:build:done": async ({ dir, logger }) => {
189	        const fileURL = new URL(filename, dir);
190	        const destDir = fileURLToPath(dir);
191	        const fileBuffer = generate(opts, finalSiteMapHref, logger);
192	        try {
193	          await fs.mkdir(destDir, { recursive: true });
194	          await fs.writeFile(fileURL, fileBuffer, "utf-8");
195	          throw "done";
196	        } catch (e) {
197	          if (e === "done") {
198	            const fileSize = getFileSizeInKilobytes(fileBuffer);
199	            logInfo(fileSize, logger, destDir);
200	          } else {
201	            throw e;
202	          }
203	        }
204	      }
205	    }
206	  };
207	}
208	
209	export { robots as default };
